import { createHash } from 'crypto';
import { db } from '../config/database';
import { logger } from '../utils/logger';
import { generateAdvisorText } from './aiService';
import { computeMatchScore } from './matchScoreService';
import type { RefineAnswers } from './matchEngine';

// ============================================================================
// "Le regard de votre chargé d'affaires" - texts generated by the AI from facts
// supplied by THIS server (never by the browser), following two distinct writing
// briefs (opportunity / compatibility). The facts define what the AI may claim;
// the examples in the briefs only define tone and structure.
// ============================================================================

export type AdviceKind = 'opportunity' | 'compatibility';

const COMMON_TONE = `Ton enthousiaste, simple et commercial : phrases courtes, mots concrets (savoir-faire, travaux, planning, contrats, prix, documents).
Le texte doit donner envie d'avancer vers l'accompagnement et ne pas ressembler à un rapport administratif : l'artisan doit comprendre « J'ai des atouts, je peux envisager de répondre et quelqu'un peut m'aider à bien le faire ».
Relie toujours l'encouragement à une aide concrète (une ou deux aides pertinentes, sans répéter tout le catalogue) : par exemple aider à choisir les réalisations à présenter, organiser les documents, préparer une réponse convaincante. Ne termine jamais par un simple « Contactez-nous ».
Ne promets ni contrat, ni marge, ni réussite garantie ; n'annonce aucune probabilité de victoire.
Varie les formulations d'une offre à l'autre sans jamais modifier les faits.
Le conseil interprète, il ne récite pas : montant, lieu, date limite, retenue de garantie et score sont déjà affichés juste au-dessus, ne les répète pas. Apporte ce que le visiteur n'a pas déjà lu : l'intérêt concret du marché, un angle pour préparer la candidature, la prochaine action. Respecte l'élision française (« en électricité », « de l'électricité »).`;

export const OPPORTUNITY_PROMPT = `Tu rédiges le conseil d'accompagnement de Marchés Direct sur une fiche opportunité.

Tu t'adresses à un artisan ou à une petite entreprise. Ton objectif est de donner envie d'étudier cette offre et de vérifier sa correspondance avec l'entreprise.

Écris trois phrases courtes, entre 40 et 65 mots :
1. Une accroche enthousiaste fondée sur l'intérêt concret du marché.
2. Une explication simple de l'aide apportée par notre équipe.
3. Une invitation à renseigner son entreprise.

Parle de travaux, planning, savoir-faire, contrats, prix et documents. Évite les termes administratifs et les formules vagues.

L'entreprise du visiteur n'est pas encore connue : ne lui attribue aucune expérience ni capacité.

Utilise exclusivement les informations transmises. N'invente ni marge, ni contrat remporté, ni relation avec le donneur d'ordre. Ne promets pas de gagner le marché.

${COMMON_TONE}

Exemple de ton pour un lot peinture séparé : « Un lot peinture pour mettre votre savoir-faire en avant ! Nous vous aidons à comprendre les travaux demandés et à préparer votre réponse sur cette spécialité. Renseignez votre entreprise pour découvrir les points qui correspondent à votre profil. »

Retourne uniquement le texte à afficher.`;

export const COMPATIBILITY_PROMPT = `Tu rédiges le conseil personnalisé de Marchés Direct après l'analyse d'une entreprise.

Tu t'adresses directement à l'artisan avec « vous ». Ton objectif est de l'encourager à avancer et de montrer l'intérêt d'être accompagné.

Écris trois phrases courtes, entre 40 et 65 mots :
1. Mets en avant le meilleur atout personnel confirmé par les données.
2. Explique comment cet atout peut être utilisé pour préparer sa candidature.
3. Propose la prochaine action indiquée.

Si aucune question n'a reçu de réponse : utilise seulement les informations connues. Invite à préciser la situation avec les quatre questions, sans rendre cette étape obligatoire.
Si certaines réponses sont positives : valorise un ou deux points utiles. Présente les réponses comme des déclarations du visiteur, pas comme des vérifications indépendantes.
Si les quatre réponses sont positives : adopte un ton plus enthousiaste et propose de passer au dossier. N'annonce ni compatibilité totale ni victoire probable.
Si une réponse est négative : ne continue pas à présenter ce point comme favorable et n'affirme jamais une disponibilité ou des moyens après un « non ». Mentionne brièvement la difficulté si elle change la décision, puis propose un échange ou une autre offre, avec un ton constructif.

Une information inconnue n'est pas un défaut. Une activité de peintre ne prouve pas une expérience sur des chantiers similaires.

Ne récite pas le score et ne le transforme pas en « chances de gagner ». Ne prétends pas qu'une personne a déjà examiné le dossier. N'invente aucun fait ni résultat client. Cite au moins un élément concret du marché ou de l'entreprise lorsqu'il est disponible.

${COMMON_TONE}

Exemples de ton (même entreprise de peinture, même marché) :
- Aucune réponse : « Votre activité de peintre correspond aux travaux recherchés : regardons cette piste ! Vous pouvez préciser votre expérience et votre organisation avec les quatre questions. Nous vous aidons ensuite à préparer la suite. »
- Expérience : oui, autres inconnues : « Vous indiquez avoir déjà réalisé des travaux similaires : mettons cette expérience en avant ! Vos réalisations peuvent aider à présenter votre savoir-faire pour ce lot peinture. Précisez votre situation ou découvrez votre dossier pour avancer avec nous. »
- Quatre oui : « Vous indiquez avoir l'expérience, les moyens et la disponibilité pour intervenir dans cette zone : passons à la suite ! Nous vous aidons à mettre ces atouts en valeur dans votre réponse. Découvrez votre dossier prérempli et préparez votre candidature avec un chargé d'affaires. »
- Calendrier : non : « Votre activité correspond aux travaux de peinture recherchés. Le calendrier que vous indiquez ne pas pouvoir respecter mérite toutefois un échange avant de préparer une candidature. Faisons le point sur cette offre ou sur un projet mieux adapté à votre planning. »

Retourne uniquement le texte à afficher.`;

const ANSWER_LABEL: Record<string, string> = { oui: 'oui', non: 'non', a_confirmer: 'inconnu' };
const ANSWER_QUESTIONS: Array<[keyof RefineAnswers, string]> = [
  ['experience', 'Expérience de travaux similaires'],
  ['capacity', 'Moyens (humains et matériels) pour ce marché'],
  ['location', 'Intervention dans la zone du marché'],
  ['calendar', 'Respect du calendrier indiqué'],
];

// Bounded in-memory cache: same facts -> same text (the advice must not change when the
// visitor returns without changing anything), and no repeated AI spend.
const CACHE_MAX = 500;
const CACHE_TTL_MS = 24 * 60 * 60 * 1000;
const cache = new Map<string, { text: string; at: number }>();
const inflight = new Map<string, Promise<string | null>>();

const cacheGet = (k: string) => {
  const hit = cache.get(k);
  if (!hit) return null;
  if (Date.now() - hit.at > CACHE_TTL_MS) { cache.delete(k); return null; }
  return hit.text;
};
const cacheSet = (k: string, text: string) => {
  if (cache.size >= CACHE_MAX) cache.delete(cache.keys().next().value as string);
  cache.set(k, { text, at: Date.now() });
};

const wordCount = (s: string) => s.trim().split(/\s+/).filter(Boolean).length;

// Output guard: a text that breaks the brief is dropped (caller shows deterministic text).
export function isAcceptableAdvice(kind: AdviceKind, text: string): boolean {
  const n = wordCount(text);
  if (n < 25 || n > 90) return false;
  if (/chances? de (gagner|succès|réussite)|marché (gagné|remporté)|garanti/i.test(text)) return false;
  if (kind === 'compatibility' && /\d\s?%/.test(text)) return false; // never recite the score
  if (/\n/.test(text.trim())) return false;
  return true;
}

async function loadOpportunityFacts(opportunityId: string) {
  const r = await db.query(
    `SELECT o.title, o.location_city, o.deadline, o.estimated_value, o.ai_extracted_facts, o.description,
            ot.code AS journey, t.name AS trade_name
     FROM opportunities o
     LEFT JOIN opportunity_types ot ON o.opportunity_type_id = ot.id
     LEFT JOIN trades t ON o.trade_id = t.id
     WHERE o.id = $1 AND o.deleted_at IS NULL`,
    [opportunityId]
  );
  const o = r.rows[0];
  if (!o) return null;
  const risks = Array.isArray(o.ai_extracted_facts?.key_risks?.value) ? o.ai_extracted_facts.key_risks.value : [];
  const mandatory = risks.find((x: any) => x && typeof x === 'object' && x.severity === 'obligatoire' && x.label);
  const deadlineMs = o.deadline ? new Date(o.deadline).getTime() : NaN;
  const lots = typeof o.description === 'string' && /\blot\s*n?°?\s*\d+/i.test(o.description);
  return {
    type_offre: o.journey === 'public_procurement' ? 'marché public' : 'offre privée',
    metier_et_prestations: o.trade_name || null,
    titre: o.title || null,
    lieu: o.location_city || null,
    calendrier_connu: !Number.isNaN(deadlineMs) && deadlineMs > Date.now(),
    avantages_identifies: lots ? ['marché organisé en lots (lot séparé possible)'] : [],
    exigence_determinante: mandatory ? String(mandatory.label).slice(0, 140) : null,
  };
}

async function resolveCompanyId(email?: string | null): Promise<string | null> {
  if (!email) return null;
  const u = await db.query('SELECT company_id FROM users WHERE email = $1 AND deleted_at IS NULL', [email]);
  return u.rows[0]?.company_id || null;
}

async function loadCompatibilityFacts(opportunityId: string, companyId: string | null, sessionId: string | null, answers: RefineAnswers) {
  const market = await loadOpportunityFacts(opportunityId);
  if (!market) return null;
  let companyName: string | null = null;
  let companyActivity: string | null = null;
  if (companyId) {
    const c = await db.query('SELECT name, industry_sector FROM companies WHERE id = $1 AND deleted_at IS NULL', [companyId]);
    companyName = c.rows[0]?.name || null;
    companyActivity = c.rows[0]?.industry_sector || null;
  }
  if ((!companyName || !companyActivity) && sessionId) {
    const l = await db.query('SELECT company_data FROM siret_lookups WHERE session_id = $1', [sessionId]);
    const d = l.rows[0]?.company_data;
    companyName = companyName || d?.name || null;
    companyActivity = companyActivity || d?.activity || null;
  }
  const result = await computeMatchScore(opportunityId, companyId, { sessionId, answers });
  return {
    marche_consulte: market,
    entreprise: { nom: companyName, activite: companyActivity },
    correspondances_calculees: result.matchCriteria.map((c) => ({
      critere: c.label,
      etat: c.status === 'match' ? 'correspond' : c.status === 'mismatch' ? 'ne correspond pas' : 'à confirmer',
      detail: c.detail,
    })),
    reponses_du_visiteur: ANSWER_QUESTIONS.map(([k, q]) => ({ question: q, reponse: ANSWER_LABEL[answers[k] || 'a_confirmer'] })),
    points_bloquants: result.matchCriteria.filter((c) => c.status === 'mismatch').map((c) => c.detail),
    marche_cloture: result.verdict?.code === 'MARKET_CLOSED',
    action_suivante: 'découvrir le dossier prérempli ou demander un échange avec un chargé d’affaires',
  };
}

export interface AdviceInput {
  kind: AdviceKind;
  opportunityId: string;
  sessionId: string | null;
  email?: string | null;
  answers: RefineAnswers;
}

// Returns the generated text, or null when the caller must use its deterministic fallback.
export async function getAdvisorAdvice(input: AdviceInput): Promise<string | null> {
  const companyId = input.kind === 'compatibility' ? await resolveCompanyId(input.email) : null;
  const facts = input.kind === 'opportunity'
    ? await loadOpportunityFacts(input.opportunityId)
    : await loadCompatibilityFacts(input.opportunityId, companyId, input.sessionId, input.answers);
  if (!facts) return null;
  if (input.kind === 'compatibility' && (facts as any).marche_cloture) return null; // closed market: deterministic text

  const factsJson = JSON.stringify(facts);
  const key = createHash('sha256').update(`${input.kind}|${factsJson}`).digest('hex');
  const hit = cacheGet(key);
  if (hit) return hit;
  const running = inflight.get(key);
  if (running) return running;

  const p = (async () => {
    try {
      const system = input.kind === 'opportunity' ? OPPORTUNITY_PROMPT : COMPATIBILITY_PROMPT;
      const text = await generateAdvisorText(system, `Informations transmises (JSON) :\n${factsJson}`);
      if (!isAcceptableAdvice(input.kind, text)) {
        logger.warn(`[advisorAdvice] rejected output for ${input.kind} (${wordCount(text)} words)`);
        return null;
      }
      cacheSet(key, text);
      return text;
    } catch (err) {
      logger.warn(`[advisorAdvice] generation failed for ${input.kind}: ${err instanceof Error ? err.message : String(err)}`);
      return null;
    } finally {
      inflight.delete(key);
    }
  })();
  inflight.set(key, p);
  return p;
}
